package com.ips.ui;
import com.ips.dao.FeatureDAO;import com.ips.model.User;import javax.swing.*;import javax.swing.border.EmptyBorder;import java.awt.*;import java.sql.SQLException;import java.util.List;
public class AnalyticsFrame extends JFrame{
 public AnalyticsFrame(User user){UIStyle.configureFrame(this,"Performance Analytics",760,560);setDefaultCloseOperation(DISPOSE_ON_CLOSE);JPanel root=new JPanel(new BorderLayout(14,14));root.setBackground(UIStyle.BACKGROUND);root.setBorder(new EmptyBorder(24,26,24,26));root.add(UIStyle.heading("Performance analytics"),BorderLayout.NORTH);try{FeatureDAO dao=new FeatureDAO();FeatureDAO.Stats s=dao.getStats(user.getId());JPanel cards=new JPanel(new GridLayout(1,4,10,10));cards.setBackground(UIStyle.BACKGROUND);cards.add(metric("Attempts",String.valueOf(s.attempts())));cards.add(metric("Questions",String.valueOf(s.questions())));cards.add(metric("Average",String.format("%.1f%%",s.average())));cards.add(metric("Best",s.best()+"%"));JPanel center=new JPanel(new BorderLayout(0,12));center.setBackground(UIStyle.BACKGROUND);center.add(cards,BorderLayout.NORTH);String[] cols={"Subject","Attempted","Correct","Accuracy"};JTable table=new JTable(dao.subjectStats(user.getId()).stream().map(a->a).toArray(String[][]::new),cols);styleTable(table);center.add(new JScrollPane(table),BorderLayout.CENTER);JLabel note=new JLabel("Accuracy is calculated from answers saved in your practice and mock interview attempts.");note.setForeground(UIStyle.MUTED);center.add(note,BorderLayout.SOUTH);root.add(center,BorderLayout.CENTER);}catch(SQLException e){root.add(new JLabel("Could not load analytics: "+e.getMessage()),BorderLayout.CENTER);}setContentPane(root);}
 private JPanel metric(String label,String value){JPanel p=new JPanel(new GridLayout(2,1,2,2));p.setBackground(UIStyle.PANEL);p.setBorder(new EmptyBorder(16,16,16,16));JLabel l=new JLabel(label);l.setForeground(UIStyle.MUTED);JLabel v=new JLabel(value);v.setForeground(UIStyle.TEXT);v.setFont(new Font("SansSerif",Font.BOLD,24));p.add(l);p.add(v);return p;}
 static void styleTable(JTable t){t.setRowHeight(28);t.setFillsViewportHeight(true);t.setAutoCreateRowSorter(true);}
}
